INSERT INTO `chatbot_display_templates` VALUES
(1,'table_generic','table','Template générique pour affichage tabulaire','<div class=\"chatbot-data-table\">\n    <table class=\"table table-hover\">\n        <thead>\n            <tr>\n                {{#each columns}}\n                <th>{{label}}</th>\n                {{/each}}\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n            <tr>\n                {{#each cells}}\n                <td>\n                    {{#if badge}}\n                        <span class=\"badge badge-{{badge}}\">{{value}}</span>\n                    {{else}}\n                        {{value}}\n                    {{/if}}\n                </td>\n                {{/each}}\n            </tr>\n            {{#if actions}}\n            <tr class=\"chatbot-row-actions\">\n                <td colspan=\"{{column_count}}\">\n                    {{#each actions}}\n                    <a href=\"{{url}}\" class=\"btn-acasi secondary btn-xs\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        {{#if icon}}<i class=\"{{icon}}\"></i> {{/if}}{{label}}\n                    </a>\n                    {{/each}}\n                </td>\n            </tr>\n            {{/if}}\n            {{/each}}\n        </tbody>\n    </table>\n    <div class=\"chatbot-table-footer\">\n        <p class=\"text-muted\">{{total_count}} résultat(s) affiché(s) sur {{total_available}}</p>\n        {{#if deep_link}}\n        <a href=\"{{deep_link}}\" class=\"btn-acasi secondary btn-sm\" target=\"_blank\" rel=\"noopener noreferrer\">\n            <i class=\"fas fa-external-link-alt\"></i> Ouvrir la page\n        </a>\n        {{/if}}\n    </div>\n</div>','\"[\\\"rows\\\",\\\"columns\\\",\\\"total_count\\\"]\"','\"[\\\"deep_link\\\",\\\"total_available\\\"]\"',1,'2025-10-21 13:35:44','2025-10-21 13:35:44'),
(2,'cards_generic','cards','Template générique pour affichage sous forme de cartes','<div class=\"chatbot-card-grid\">\n    {{#each cards}}\n    <div class=\"chatbot-card\">\n        <div class=\"chatbot-card-header\">\n            <div>\n                <h5>{{title}}</h5>\n                <p class=\"chatbot-card-subtitle\">{{subtitle}}</p>\n            </div>\n            {{#if badges}}\n            <div class=\"chatbot-card-badges\">\n                {{#each badges}}\n                <span class=\"badge badge-{{style}}\">{{label}}</span>\n                {{/each}}\n            </div>\n            {{/if}}\n        </div>\n        {{#if meta}}\n        <div class=\"chatbot-card-body\">\n            {{#each meta}}\n            <div class=\"chatbot-card-row\">\n                <span class=\"chatbot-card-label\">{{label}}</span>\n                <span class=\"chatbot-card-value\">{{value}}</span>\n            </div>\n            {{/each}}\n        </div>\n        {{/if}}\n        {{#if actions}}\n        <div class=\"chatbot-card-actions\">\n            {{#each actions}}\n            <a href=\"{{url}}\" class=\"btn-acasi secondary btn-xs\" target=\"_blank\" rel=\"noopener noreferrer\">\n                {{#if icon}}<i class=\"{{icon}}\"></i> {{/if}}{{label}}\n            </a>\n            {{/each}}\n        </div>\n        {{/if}}\n    </div>\n    {{/each}}\n    <div class=\"chatbot-table-footer\">\n        <p class=\"text-muted\">{{total_count}} élément(s) affiché(s) sur {{total_available}}</p>\n        {{#if deep_link}}\n        <a href=\"{{deep_link}}\" class=\"btn-acasi secondary btn-sm\" target=\"_blank\" rel=\"noopener noreferrer\">\n            <i class=\"fas fa-external-link-alt\"></i> Ouvrir la page\n        </a>\n        {{/if}}\n    </div>\n</div>','\"[\\\"cards\\\",\\\"total_count\\\"]\"','\"[\\\"deep_link\\\",\\\"total_available\\\"]\"',1,'2025-10-21 13:35:44','2025-10-21 13:35:44'),
(3,'paiements_table','table','Template pour afficher liste de paiements','<div class=\"chatbot-data-table\">\n    <table class=\"table table-hover\">\n        <thead>\n            <tr>\n                <th>Étudiant</th>\n                <th>Montant</th>\n                <th>Statut</th>\n                <th>Date</th>\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n            <tr>\n                <td>{{etudiant_nom}}</td>\n                <td>{{montant_formatte}}</td>\n                <td><span class=\"badge badge-{{statut_class}}\">{{statut}}</span></td>\n                <td>{{date_paiement}}</td>\n            </tr>\n            {{/each}}\n        </tbody>\n    </table>\n    <div class=\"chatbot-table-footer\">\n        <p class=\"text-muted\">{{total_count}} paiement(s) affiché(s) sur {{total_available}}</p>\n        {{#if deep_link}}\n        <a href=\"{{deep_link}}\" class=\"btn-acasi secondary btn-sm\">\n            <i class=\"fas fa-external-link-alt\"></i> Voir tous les paiements\n        </a>\n        {{/if}}\n    </div>\n</div>','\"[\\\"rows\\\",\\\"total_count\\\"]\"','\"[\\\"deep_link\\\",\\\"total_available\\\"]\"',1,'2025-10-21 13:35:44','2025-10-21 13:35:44'),
(4,'inscriptions_table','table','Template pour afficher liste inscriptions','<div class=\"chatbot-data-table\">\n    <table class=\"table table-hover\">\n        <thead>\n            <tr>\n                <th>Étudiant</th>\n                <th>Classe</th>\n                <th>Type</th>\n                <th>Statut</th>\n                <th>Date</th>\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n            <tr>\n                <td>{{etudiant_nom}}</td>\n                <td>{{classe}}</td>\n                <td>{{type_inscription}}</td>\n                <td><span class=\"badge badge-{{statut_class}}\">{{statut}}</span></td>\n                <td>{{date_inscription}}</td>\n            </tr>\n            {{/each}}\n        </tbody>\n    </table>\n    <div class=\"chatbot-table-footer\">\n        <p class=\"text-muted\">{{total_count}} inscription(s) affichée(s) sur {{total_available}}</p>\n        {{#if deep_link}}\n        <a href=\"{{deep_link}}\" class=\"btn-acasi secondary btn-sm\">\n            <i class=\"fas fa-external-link-alt\"></i> Voir toutes les inscriptions\n        </a>\n        {{/if}}\n    </div>\n</div>','\"[\\\"rows\\\",\\\"total_count\\\"]\"','\"[\\\"deep_link\\\",\\\"total_available\\\"]\"',1,'2025-10-21 13:35:44','2025-10-21 13:35:44'),
(5,'etudiants_table','table','Template pour afficher liste étudiants','<div class=\"chatbot-data-table\">\n    <table class=\"table table-hover\">\n        <thead>\n            <tr>\n                <th>Nom complet</th>\n                <th>Matricule</th>\n                <th>Classe</th>\n                <th>Statut</th>\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n            <tr>\n                <td>{{nom_complet}}</td>\n                <td>{{matricule}}</td>\n                <td>{{classe}}</td>\n                <td><span class=\"badge badge-{{statut_class}}\">{{statut}}</span></td>\n            </tr>\n            {{/each}}\n        </tbody>\n    </table>\n    <div class=\"chatbot-table-footer\">\n        <p class=\"text-muted\">{{total_count}} étudiant(s) affiché(s) sur {{total_available}}</p>\n        {{#if deep_link}}\n        <a href=\"{{deep_link}}\" class=\"btn-acasi secondary btn-sm\">\n            <i class=\"fas fa-external-link-alt\"></i> Voir tous les étudiants\n        </a>\n        {{/if}}\n    </div>\n</div>','\"[\\\"rows\\\",\\\"total_count\\\"]\"','\"[\\\"deep_link\\\",\\\"total_available\\\"]\"',1,'2025-10-21 13:35:44','2025-10-21 13:35:44');
